/**
 * Returns TypeScript source for an Angular component that wraps RiskLab Charts.
 * In a real Angular project, paste `getAngularComponentSource()` into a file,
 * or use the component factory `createAngularChart` directly.
 *
 * The built component:
 * - Accepts `[config]` input
 * - Accepts `[theme]` input
 * - Emits `(chartReady)` output with the engine ref
 * - Supports OnPush change detection
 * - Auto-sizes to container via ResizeObserver
 * - Cleans up on `ngOnDestroy`
 */
export function getAngularComponentSource(): string {
  return `
import {
  Component, Input, Output, EventEmitter,
  ElementRef, OnInit, OnChanges, OnDestroy, AfterViewInit,
  ChangeDetectionStrategy, SimpleChanges, NgModule,
} from '@angular/core';
import { createAngularChart, type AngularChartRef } from '@risklab/charts-angular';
import type { ChartConfig, ThemeConfig } from '@risklab/charts';

@Component({
  selector: 'uc-chart',
  standalone: true,
  template: '<div #chartHost style="width:100%;height:100%"></div>',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RiskLabChartComponent implements AfterViewInit, OnChanges, OnDestroy {
  @Input() config!: ChartConfig;
  @Input() theme?: string | ThemeConfig;
  @Output() chartReady = new EventEmitter<AngularChartRef>();

  private chartRef?: AngularChartRef;
  private resizeObserver?: ResizeObserver;

  constructor(private el: ElementRef<HTMLElement>) {}

  ngAfterViewInit(): void {
    this.mount();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!this.chartRef) return;
    if (changes['config']) {
      this.chartRef.update(this.config);
    }
    if (changes['theme'] && this.theme) {
      this.chartRef.setTheme(this.theme);
    }
  }

  ngOnDestroy(): void {
    this.resizeObserver?.disconnect();
    this.chartRef?.destroy();
  }

  private mount(): void {
    const host = this.el.nativeElement;
    this.chartRef = createAngularChart(host, {
      ...this.config,
      ...(this.theme ? { theme: this.theme } : {}),
    });

    this.resizeObserver = new ResizeObserver(() => {
      this.chartRef?.engine?.resize();
    });
    this.resizeObserver.observe(host);

    this.chartReady.emit(this.chartRef);
  }
}

/** NgModule for legacy Angular apps (pre-standalone). */
@NgModule({
  imports: [RiskLabChartComponent],
  exports: [RiskLabChartComponent],
})
export class RiskLabModule {}
`.trim();
}

