/**
 * Returns TypeScript source for an injectable Angular service that manages
 * a registry of chart instances, useful for dashboard apps.
 */
export function getAngularServiceSource(): string {
  return `
import { Injectable, OnDestroy } from '@angular/core';
import type { AngularChartRef } from '@risklab/charts-angular';

@Injectable({ providedIn: 'root' })
export class RiskLabService implements OnDestroy {
  private registry = new Map<string, AngularChartRef>();

  register(id: string, ref: AngularChartRef): void {
    this.registry.set(id, ref);
  }

  get(id: string): AngularChartRef | undefined {
    return this.registry.get(id);
  }

  remove(id: string): void {
    this.registry.get(id)?.destroy();
    this.registry.delete(id);
  }

  exportAll(format: 'png' | 'svg' | 'csv' = 'png'): Promise<Array<{ id: string; data: Blob | string }>> {
    return Promise.all(
      [...this.registry.entries()].map(async ([id, ref]) => ({
        id,
        data: await ref.exportChart(format),
      }))
    );
  }

  ngOnDestroy(): void {
    for (const ref of this.registry.values()) ref.destroy();
    this.registry.clear();
  }
}
`.trim();
}
